import{_ as n,C as t,o as i,c,E as r,a2 as o}from"./chunks/framework.Cc8dJFaW.js";const _=JSON.parse('{"title":"回执丢失后，操作仍然没有定论","description":"","frontmatter":{"title":"回执丢失后，操作仍然没有定论","article_type":"engineering-insight","edition":"research-center","research_question":"外部操作丢失回执后，哪些身份一致的证据足以进入对账，哪些状态仍须保留而不能重新提交？","summary":"比较原子效果边界与具体订单恢复路径，区分回执丢失后记录格式、操作身份与恢复处置的不同证据责任。","sources":["https://arxiv.org/html/2611.32032v1","https://raw.githubusercontent.com/openkedge/openkedge/80836b200ec56d8d4ef845cf86c0c2873314b287/research/pieq/pieq/hardened.py","https://arxiv.org/html/2611.24845v1","https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/sdk_order_gate.py","https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/pending_action.py"],"date":"2026-11-26","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261126-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-26-sig-20261126-003-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-26-sig-20261126-003.md","filePath":"zh/engineering/2026-11-26-sig-20261126-003.md","lastUpdated":null}'),l={name:"zh/engineering/2026-11-26-sig-20261126-003.md"};function s(h,e,p,g,b,f){const a=t("ArticleCover"),d=t("ArticleTableScroll");return i(),c("div",null,[r(a,{image:"/assets/covers/daily-2026-11-26-sig-20261126-003-final-cover.png",kicker:"研究成果",title:"回执丢失后，操作仍然没有定论",summary:"比较原子效果边界与具体订单恢复路径，区分回执丢失后记录格式、操作身份与恢复处置的不同证据责任。",version:"2026-11-26",languageHref:"/en/engineering/2026-11-26-sig-20261126-003",languageLabel:"English"}),r(d,{language:"zh"}),e[0]||(e[0]=o('<h1 id="回执丢失后-操作仍然没有定论" tabindex="-1">回执丢失后，操作仍然没有定论 <a class="header-anchor" href="#回执丢失后-操作仍然没有定论" aria-label="Permalink to &quot;回执丢失后，操作仍然没有定论&quot;">​</a></h1><p>订单提交后连接断开，本地只剩一条待决记录。此时再发一次，可能重复下单；直接清掉记录，又可能失去追踪已发生效果的责任。这是一个示意故障场景。本文的判断是：超时没有裁定远程结果，即使取回格式正确的记录，也要先检查它属于哪次操作，再决定如何恢复。读者可以据此写出一张保留、再验证与终态清理的处置表。</p><h2 id="本地提交与远程效果之间的缝隙" tabindex="-1">本地提交与远程效果之间的缝隙 <a class="header-anchor" href="#本地提交与远程效果之间的缝隙" aria-label="Permalink to &quot;本地提交与远程效果之间的缝隙&quot;">​</a></h2><p>PIEQ（来源隔离的认知仲裁研究）区分两种情形：去重记录与受保护效果共用原子边界，以及真正发生在远端的操作。前一种设计可在同一边界内联动裁决；后一种如果没有共同事务，网络确认丢失后，调用方不能只凭本地超时判定远端未执行。论文要求保留未知状态并对账，不能把本地去重直接升级成远程恰好一次效果。<a href="https://arxiv.org/html/2611.32032v1" target="_blank" rel="noreferrer">论文第 5.2 节</a></p><p>固定实现进一步显示，控制器仅在验证到经过隔离的无效果结果时释放风险敞口，否则保留未知状态。这里的观察不包含内存台账的崩溃持久性证明。<a href="https://raw.githubusercontent.com/openkedge/openkedge/80836b200ec56d8d4ef845cf86c0c2873314b287/research/pieq/pieq/hardened.py" target="_blank" rel="noreferrer">控制器源码</a></p><p>这个边界问题并不意味着“永远不重试”。如果目标系统提供经验证的原生幂等合同，某些重复请求可以安全合并；关键是合同是否覆盖同一操作、持续多长时间，以及失败边界是什么。本轮没有测试这类目标保证，所以不能据此宣布某个远端调用可以安全重发。</p><h2 id="取回订单-还要确认是同一笔" tabindex="-1">取回订单，还要确认是同一笔 <a class="header-anchor" href="#取回订单-还要确认是同一笔" aria-label="Permalink to &quot;取回订单，还要确认是同一笔&quot;">​</a></h2><p>独立作者团队的 Vibe-Trading（智能体交易研究系统）提供了具体对账路径。论文区分研究证据与下单授权，并区分已接受、已拒绝和未决订单；所查实现会在提交前保存面向 Alpaca（券商接口）的操作意图。论文与其仓库属于同一个作者主体，不因材料形式不同而增加来源数量。<a href="https://arxiv.org/html/2611.24845v1" target="_blank" rel="noreferrer">论文</a></p><p>固定版本的恢复函数按原客户端订单编号查询外部结果，不重新提交订单。后续校验要求结果具有券商订单编号，并比较客户端编号、标的、方向、订单类型与有效期，再比较数量、名义金额与限价；时间必须带时区，成交量不能为负，状态必须属于已知集合。它检查的是恢复证据与待决请求的一致性，不能单独认证提供者说的是真话。<a href="https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/sdk_order_gate.py" target="_blank" rel="noreferrer">订单恢复源码</a></p><p>待决记录模块还把请求、客户端编号、券商编号、阶段与持仓归因连接起来，但该模块支持的是上述券商路径。不能把这份证据写成全部连接器已经具有相同恢复能力。<a href="https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/pending_action.py" target="_blank" rel="noreferrer">待决记录源码</a></p><p>这里的独立性是作者独立：前者团队给出原子边界和保留责任的研究，后者团队给出具体订单实现。它们能支持机制比较，不构成相互复现实验，更不能推出实盘可靠性或投资收益。</p><h2 id="已成交、成交量零-为什么仍能通过一层检查" tabindex="-1">“已成交、成交量零”为什么仍能通过一层检查 <a class="header-anchor" href="#已成交、成交量零-为什么仍能通过一层检查" aria-label="Permalink to &quot;“已成交、成交量零”为什么仍能通过一层检查&quot;">​</a></h2><p>同次研究分析已运行两组内部隔离探针：十七个记录校验用例、五个恢复用例。方法从固定源码提取原函数，用合成请求、券商应答和外部边界替身运行；计数、持久审计、待决迁移和清理只记录调用意图，没有实现真实存储。这里消费的是已完成的实验，Production（文章生产阶段）没有重新实验。</p><p>记录校验拒绝身份或数量不符、无时区时间、未知状态与不合法数字；数值十与十点零零视为相等。一个刻意构造的反例是：状态写“已成交”，成交量却为零。记录校验仍返回规范化结果；随后恢复函数识别状态与成交量矛盾，走停止分支。因此，单看前一函数“接受”就宣布系统放行，会读错层次。</p><table tabindex="0"><thead><tr><th>合成输入</th><th>被观察的层</th><th>本轮实际结果</th></tr></thead><tbody><tr><td>客户端编号或数量不符</td><td>记录校验</td><td>不形成可用恢复记录</td></tr><tr><td>查询抛错，或取回身份不符</td><td>恢复函数</td><td>返回未决拒绝，不重提订单</td></tr><tr><td>身份一致、仍在工作中的订单</td><td>恢复函数</td><td>请求计数与策略再验证</td></tr><tr><td>身份一致、明确拒绝的零成交订单</td><td>恢复函数</td><td>请求清理待决记录</td></tr><tr><td>“已成交”且成交量为零</td><td>先校验、后恢复</td><td>前层接受，后层停止</td></tr></tbody></table><p><a href="/joinwell52/assets/evidence/2026-11-26-sig-20261126-003/experiment-evidence.json">内部探针的完整用例与结果</a></p><p>这正是分层解释的价值：格式和字段一致性负责筛出可解释材料，恢复策略负责决定材料意味着什么。本轮五个恢复分支没有调用重新下单，但这不证明所有上游入口都不会重发，也不证明替身记录的清理已在真实磁盘持久化。</p><h2 id="让待决责任跟着证据走" tabindex="-1">让待决责任跟着证据走 <a class="header-anchor" href="#让待决责任跟着证据走" aria-label="Permalink to &quot;让待决责任跟着证据走&quot;">​</a></h2><p>下面是一份供远程写操作使用的建议责任表，不是对所有交易系统已有行为的描述。它把“等待”“拒绝使用错误证据”“停止处理矛盾”分开，避免用一个失败标签覆盖所有后续动作。</p><table tabindex="0"><thead><tr><th>责任主体与输入</th><th>应保留的产物</th><th>处置边界</th></tr></thead><tbody><tr><td>提交方构造操作意图</td><td>可关联到具体操作的身份与请求</td><td>尚未发送，与已发未确认分开</td></tr><tr><td>恢复方面对超时</td><td>原待决记录与查询尝试</td><td>读取失败保留未决，不能宣称未执行</td></tr><tr><td>证据校验方接收外部记录</td><td>一致性检查与规范化记录</td><td>身份不符不应用到当前操作</td></tr><tr><td>恢复策略接收工作中状态</td><td>责任归属与再验证要求</td><td>仍在工作中，不等于重新获准写入</td></tr><tr><td>清理方接收确切终态</td><td>对应操作的终态与清理结果</td><td>清理失败仍需保留恢复责任</td></tr></tbody></table><p>在这一路径中，“明确拒绝”与“工作中”产生不同处置；部分成交又涉及持仓归因，不能沿用零成交清理。审查时应把待决记录、每日计数、审计与外部订单的持久性逐项列出。代码中存在清理调用，不代表它与券商效果原子完成。</p><h2 id="下一次故障注入应回答什么" tabindex="-1">下一次故障注入应回答什么 <a class="header-anchor" href="#下一次故障注入应回答什么" aria-label="Permalink to &quot;下一次故障注入应回答什么&quot;">​</a></h2><p>本轮结果限定于固定版本：具体恢复实现来自提交 2134f408b1cd715c74fa8c5021f4402d50b00ea8，原子边界比较来自提交 80836b200ec56d8d4ef845cf86c0c2873314b287 与论文第一版。前者是较晚的实现证据，不等同于论文评测时冻结的代码。完整券商服务、文件锁持久性、审计失败、部分成交归因与多客户端竞争均未在这些探针中复现。</p><p>PIEQ 论文中的物理测试仍是作者报告。其共享宿主内核和每秒一次的观察方式，不能排除更短时间窗的双主状态；原生集群保护也不能归功于逻辑推理本身。论文发表或源码开放，只确立材料来源，不补足独立验证。<a href="https://arxiv.org/html/2611.32032v1" target="_blank" rel="noreferrer">原子边界与物理测试说明</a></p><p>下一步可在有授权的测试环境中注入：外部记录格式正确但过期、审计落盘失败、清理中断、部分成交后重启，以及另一个客户端同时操作。还应验证目标原生幂等合同。若这些问题没有答案，合理结果可能仍是保留待决并人工对账。超时后的恢复价值，首先在于没有丢掉责任，而不是更快地宣布完成。</p><h3 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h3><ul><li>OpenKedge（论文作者机构）：《来源隔离的认知仲裁：智能体控制平面中绑定执行的证据认证与可能世界安全判定》，论文第一版，2026-11-24。<a href="https://arxiv.org/html/2611.32032v1" target="_blank" rel="noreferrer">原子边界与物理测试</a>；<a href="https://raw.githubusercontent.com/openkedge/openkedge/80836b200ec56d8d4ef845cf86c0c2873314b287/research/pieq/pieq/hardened.py" target="_blank" rel="noreferrer">控制器源码</a>，固定提交 80836b200ec56d8d4ef845cf86c0c2873314b287。</li><li>香港大学作者团队：《Vibe-Trading：走向智能体原生交易》，论文第一版，2026-11-18。<a href="https://arxiv.org/html/2611.24845v1" target="_blank" rel="noreferrer">研究与执行边界</a>；<a href="https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/sdk_order_gate.py" target="_blank" rel="noreferrer">订单恢复</a>与<a href="https://raw.githubusercontent.com/HKUDS/Vibe-Trading/2134f408b1cd715c74fa8c5021f4402d50b00ea8/agent/src/live/pending_action.py" target="_blank" rel="noreferrer">待决记录</a>，固定提交 2134f408b1cd715c74fa8c5021f4402d50b00ea8。</li><li>本研究中心：2026-11-26 内部隔离记录校验与恢复实验；未连接真实券商，也未验证存储持久性。<a href="/joinwell52/assets/evidence/2026-11-26-sig-20261126-003/experiment-evidence.json">逐例输入与结果</a>。</li></ul>',27))])}const m=n(l,[["render",s]]);export{_ as __pageData,m as default};
